          "advanced": false,
          "help": "天气作为本地权重因子影响情绪回落目标。",
          "details": "本地定时轮询实况天气，不经大模型；只调整四维的回落目标，不改当前值、不落库，也不参与六情绪计算。关闭后天气只作为日记与梦境的背景文字。",
          "example": "需要TA的心情随晴雨缓慢变化：开启；只想保留天气文字：关闭。",
